using System.ComponentModel.DataAnnotations; using OrderFlow.MVC.Models;
namespace OrderFlow.MVC.ViewModels { public class CustomerRequestCreateViewModel { [Required] public int CustomerId { get; set; } public int? OrderId { get; set; } [Required] public RequestType Type { get; set; } [Required] public RequestPriority Priority { get; set; } [Required, StringLength(1600)] public string Description { get; set; } } public class CustomerRequestUpdateViewModel { [Required] public int CustomerRequestId { get; set; } [Required] public RequestStatus Status { get; set; } public int? AssignedEmployeeUserId { get; set; } [StringLength(1600)] public string Resolution { get; set; } [Required, StringLength(1600)] public string Message { get; set; } public bool IsVisibleToCustomer { get; set; } = true; } }
